from pathlib import Path
import json,subprocess,hashlib,importlib.util
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[2];WORK=ROOT/'work/opening-v3-hero';OUT=ROOT/'outputs/opening-v3-hero'
spec=importlib.util.spec_from_file_location('hero',WORK/'render_silent_hero.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
checks={};clips=[];sheet=Image.new('RGB',(1080,534),(28,28,28));draw=ImageDraw.Draw(sheet)
for index,(kind,(name,count)) in enumerate(m.CLIPS.items()):
 p=OUT/(name+'.mp4');probe=json.loads(subprocess.check_output(['ffprobe','-v','error','-count_frames','-show_streams','-of','json',str(p)]));v=probe['streams'][0]
 decode=subprocess.run(['ffmpeg','-v','error','-i',str(p),'-f','null','-'],capture_output=True,text=True,check=True)
 result={'1080x1920':(v['width'],v['height'])==(1080,1920),'30fps':v['avg_frame_rate']=='30/1','frame_count':int(v['nb_read_frames'])==count,'H264':v['codec_name']=='h264','silent':len(probe['streams'])==1,'full_decode':not decode.stderr.strip()}
 assert all(result.values()),(kind,result);checks[kind]=result
 encoded=OUT/(name+'-encoded.png');subprocess.run(['ffmpeg','-v','error','-y','-ss',str(count/60),'-i',str(p),'-frames:v','1',str(encoded)],check=True)
 with Image.open(encoded) as im:im.thumbnail((270,480));sheet.paste(im,(index*270,0))
 draw.text((index*270+5,488),f'{kind} · {count}f · {count/30:.1f}s',fill='white')
 clips.append({'shot':kind,'name':name,'path':str(p),'frames':count,'duration':count/30,'sha256':hashlib.file_digest(p.open('rb'),'sha256').hexdigest(),'audio':False})
sheet.save(OUT/'HERO_CONTACT_SHEET.png')
quad_final=[[(x-55)*1080/970,(y-300)*1920/1525] for x,y in m.QUAD]
book_bottom=max(y for x,y in quad_final)
metadata={'scope':'Opening silent hero shots only; user authorized ongoing rendering. No later-film/native-plate render performed here.','fps':30,'width':1080,'height':1920,'clips':clips,'camera_geography':{'C1':'Near front board, looks toward rear cupboards. Teacher/board are offscreen behind/near camera.','teacher_eyeline':'Camera-left / near the frontal lens, toward room FRONT. Not toward rear wall.','B_limitation':'Wider C1 reverse context only; not a teacher-board view.'},'handedness':{'writing_hand':'anatomical RIGHT','C1_pencil_side':'screen-LEFT','C3_notebook_pencil_side':'screen-RIGHT','anchor_hand':'opposite side in each view'},'notebook':{'shared_texture_source':str(ROOT/'outputs/opening-v3-notebook'),'C1_transform':'rotate exact pupil-readable texture 180 degrees; never mirror','C1_cricket_page':'screen-LEFT','F_end_state':'open maths spread covers cricket notebook; pencil parked to screen-left','I_start_state':'cricket spread already revealed; place after H dense-cricket insert, not directly after F covered end-state'},'caption_clearance':{'suggested_box':{'x':80,'y':1730,'width':920,'height':150},'max_main_notebook_y':book_bottom,'main_notebook_gap_before_caption_box':1730-book_bottom,'caption_burn_in':False},'flexible_anchors':{'A':{'write_start':0,'one_stroke_finished':1.4,'hold_or_extend':'brief first/last pose holds; do not reverse pencil/ink contact'},'B':{'context_reveal':0,'flexibility':'24 of the 27 frames may be used without changing action identity'},'F':{'pencil_freeze':.17,'eyes_head_attention_begin':.17,'near_left_pose':.25,'far_left_pose':.34,'park_begin':.52,'pencil_release_cover_begin':.72,'maths_cover_landed':1.12,'tail_hold':'1.12–1.60s; extend this settled hold rather than stretching concealment gesture'},'I':{'neutral_recover':0,'wry_head_tilt':.16,'resume_writing':.65,'tail_hold':'settled writing after .65s may be extended briefly'}},'performance':'Small retained-geometry key-pose snaps bracketed by continuous torso/hand/pen movement, not lip sync. Restrained original neutral/crooked mouth rather than the V2 broad laugh.','limitations':['Mostly still approved background artwork.','Lower seated anatomy is desk-occluded; no full seated-rig audit.','2.5D hand/page contact is not simulated 3D paper physics.','These are silent source clips; Michael timing, captions and sound design belong to final assembly.']}
(OUT/'HERO_METADATA.json').write_text(json.dumps(metadata,indent=2));(OUT/'HERO_TECHNICAL_QA.json').write_text(json.dumps({'checks':checks,'all_passed':True},indent=2))
print(json.dumps({'checks':checks,'notebook_bottom_y':book_bottom,'caption_gap_px':1730-book_bottom},indent=2))
